import React from 'react';

function Banner() {
  return (
    <div className="bannerParentDiv" style={{ backgroundColor: '#002f34', color: 'white', padding: '12px 20px' }}>
      <div className="bannerChildDiv" style={{ display: 'flex', gap: '25px', alignItems: 'center', fontSize: '14px', flexWrap: 'wrap' }}>
        <span style={{ fontWeight: 'bold', letterSpacing: '0.5px' }}>ALL CATEGORIES</span>
        <span style={{ cursor: 'pointer' }}>Vehicles</span>
        <span style={{ cursor: 'pointer' }}>Electronics</span>
        <span style={{ cursor: 'pointer' }}>Clothing</span>
        <span style={{ cursor: 'pointer' }}>Furniture</span>
        <span style={{ cursor: 'pointer' }}>Books</span>
      </div>
    </div>
  );
}

export default Banner;
